<?php
require __DIR__.'/_auth.php';$pdo=admin_db();if(!$pdo)exit('Database unavailable.');$id=(int)($_GET['id']??0);$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'save';if($action==='delete'&&$id){$pdo->prepare('DELETE FROM destinations WHERE id=?')->execute([$id]);header('Location:/admin/destinations.php');exit;}$name=trim($_POST['name']??'');$slug=preg_replace('/[^a-z0-9-]+/','-',strtolower(trim($_POST['slug']??$name)));$status=($_POST['status']??'draft')==='published'?'published':'draft';$data=[$slug,$name,trim($_POST['summary']??''),trim($_POST['body']??''),trim($_POST['featured_image']??''),$status,trim($_POST['meta_title']??''),trim($_POST['meta_description']??'')];if($id){$st=$pdo->prepare('UPDATE destinations SET slug=?,name=?,summary=?,body=?,featured_image=?,status=?,meta_title=?,meta_description=?,updated_at=NOW() WHERE id=?');$st->execute([...$data,$id]);}else{$st=$pdo->prepare('INSERT INTO destinations(slug,name,summary,body,featured_image,status,meta_title,meta_description,updated_at) VALUES(?,?,?,?,?,?,?,?,NOW())');$st->execute($data);$id=(int)$pdo->lastInsertId();}$msg='Destination saved.';}$row=null;if($id){$st=$pdo->prepare('SELECT * FROM destinations WHERE id=?');$st->execute([$id]);$row=$st->fetch();}$list=$pdo->query('SELECT id,name,slug,status,updated_at FROM destinations ORDER BY updated_at DESC')->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><link rel="stylesheet" href="/assets/css/style.css"><title>Destination CMS</title></head><body><main class="section wrap"><div class="section-head"><div><span class="eyebrow dark-text">CMS</span><h1>Destinations</h1></div><div><a class="btn light" href="/admin/">Dashboard</a> <a class="btn dark" href="/admin/destinations.php">New Destination</a></div></div><?php if($msg):?><p><strong><?=e($msg)?></strong></p><?php endif;?><div class="content-layout"><section><form class="contact-form" method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input name="name" value="<?=e($row['name']??'')?>" placeholder="Destination name" required><input name="slug" value="<?=e($row['slug']??'')?>" placeholder="slug"><textarea name="summary" placeholder="Short summary"><?=e($row['summary']??'')?></textarea><textarea name="body" style="min-height:320px" placeholder="Detailed destination content"><?=e($row['body']??'')?></textarea><input name="featured_image" value="<?=e($row['featured_image']??'')?>" placeholder="Featured image path"><input name="meta_title" value="<?=e($row['meta_title']??'')?>" placeholder="SEO title"><textarea name="meta_description" placeholder="SEO description"><?=e($row['meta_description']??'')?></textarea><select name="status"><option value="draft" <?=($row['status']??'draft')==='draft'?'selected':''?>>Draft</option><option value="published" <?=($row['status']??'')==='published'?'selected':''?>>Published</option></select><button class="btn gold">Save Destination</button><?php if($id):?><button class="btn" name="action" value="delete" onclick="return confirm('Delete destination?')">Delete</button><?php endif;?></form></section><aside><h2>Existing Destinations</h2><?php foreach($list as $r):?><p><a href="/admin/destinations.php?id=<?=$r['id']?>"><strong><?=e($r['name'])?></strong></a><br><small>/destination/<?=e($r['slug'])?> · <?=e($r['status'])?></small></p><?php endforeach;?></aside></div></main></body></html>
